#!/usr/bin/env python3
# ruff: noqa: T201 allow print statements
"""
CI guard: a product's frontend belongs in ``products/<name>/frontend/``, not in
``frontend/src/scenes/<name>/``.

Some products exist as a directory under ``products/`` while their UI still lives
under ``frontend/src/scenes/``. That split has a cost beyond tidiness:
``.github/scripts/trunk-impacted-targets.js`` assigns merge-queue lanes by path, so a
change anywhere under ``frontend/`` reports ``fe:core`` plus every ``fe:product:*``
target and serializes against every other frontend PR. A change confined to
``products/<name>/frontend/`` reports only ``fe:product:<name>``.

A dependency graph cannot replace the path signal. The frontend module graph contains
a large strongly connected component spanning many products, and every member of an
SCC has identical reverse-reachability by definition, so the closure from a file under
``frontend/src`` reaches most products no matter what changed. That makes the directory
a real boundary rather than a stylistic preference.

Two tiers, both derived mechanically from the tree so there is nothing to curate:

``enforce``
    ``products/<name>/frontend`` holds at least as many hand-written files as
    ``frontend/src/scenes/<name>``. The destination is already the product's real
    home, so growing the scenes/ copy is backsliding. Growth fails CI.

``observe``
    The migration hasn't reached halfway. Growth is reported, not failed, because a
    hard gate here would block a steady stream of legitimate work in trees nobody has
    started moving. A dir promotes itself to ``enforce`` once the migration passes
    halfway; no one has to remember to flip it.

Files under a ``generated/`` directory don't count toward either side: orval writes
those, so they'd otherwise tip a product into ``enforce`` before a human moved anything.

A new top-level scene dir fails when ``products/<name>/`` already exists, because the
destination is then unambiguous. A new dir with no counterpart only warns: settings,
onboarding, billing and friends are app-level scenes with nowhere else to go, and
guessing which of those should have been a product is exactly the judgment call a
linter should not be making.

The baseline is the mechanical output of ``--regenerate-baseline``. Hand editing it
degrades it into a curated allowlist.

Usage:
    python .github/scripts/check-scene-product-split.py
    python .github/scripts/check-scene-product-split.py --regenerate-baseline

Exit codes:
    0 - No new coupling (may pass with backslide/shrink warnings)
    1 - A new scene directory, or growth in an `enforce` tree
"""

from __future__ import annotations

import sys
import argparse
from dataclasses import dataclass
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent.parent
SCENES_ROOT = REPO_ROOT / "frontend/src/scenes"
PRODUCTS_ROOT = REPO_ROOT / "products"
BASELINE_FILE = SCENES_ROOT / "product_split_baseline.txt"

SOURCE_SUFFIXES = (".ts", ".tsx")

BASELINE_HEADER = (
    "# Product UI still living in frontend/src/scenes/ instead of products/<name>/frontend/.\n"
    "#\n"
    "# DO NOT EDIT BY HAND. This file is the mechanical output of\n"
    "# `--regenerate-baseline`. Hand-adding entries turns it back into a curated\n"
    "# allowlist and defeats the shrink-only guarantee.\n"
    "#\n"
    "# Auto-generated by .github/scripts/check-scene-product-split.py\n"
    "# Regenerate: python .github/scripts/check-scene-product-split.py --regenerate-baseline\n"
    "#\n"
    "# Each line is `<mode>\\t<scene_files>\\t<product_files>\\t<scene_dir>`. Move a\n"
    "# feature into products/<name>/frontend/, then regenerate to shrink. A dir flips\n"
    "# from `observe` to `enforce` on its own once products/ holds the larger half.\n"
)


@dataclass(frozen=True)
class SceneDir:
    name: str
    scene_files: int
    product: str | None
    product_files: int

    @property
    def mode(self) -> str:
        if self.product is None:
            return "unowned"
        return "enforce" if self.product_files >= self.scene_files else "observe"

    @property
    def destination(self) -> str:
        return f"products/{self.product}/frontend/"


def count_sources(root: Path) -> int:
    """Hand-written .ts/.tsx under root. `generated/` trees are orval's output, not migration progress."""
    if not root.is_dir():
        return 0
    return sum(
        1
        for path in root.rglob("*")
        if path.suffix in SOURCE_SUFFIXES and path.is_file() and "generated" not in path.relative_to(root).parts
    )


def product_directories() -> dict[str, str]:
    """Normalized product name -> real directory name. scenes/ uses kebab-case, products/ snake_case."""
    if not PRODUCTS_ROOT.is_dir():
        return {}
    return {entry.name.replace("_", ""): entry.name for entry in sorted(PRODUCTS_ROOT.iterdir()) if entry.is_dir()}


def scan_current() -> dict[str, SceneDir]:
    if not SCENES_ROOT.is_dir():
        return {}
    products = product_directories()
    found: dict[str, SceneDir] = {}
    for entry in sorted(SCENES_ROOT.iterdir()):
        if not entry.is_dir():
            continue
        scene_files = count_sources(entry)
        if scene_files == 0:
            continue
        product = products.get(entry.name.replace("-", "").replace("_", ""))
        found[entry.name] = SceneDir(
            name=entry.name,
            scene_files=scene_files,
            product=product,
            product_files=count_sources(PRODUCTS_ROOT / product / "frontend") if product else 0,
        )
    return found


def read_baseline() -> dict[str, SceneDir]:
    if not BASELINE_FILE.exists():
        return {}
    baseline: dict[str, SceneDir] = {}
    products = product_directories()
    for line in BASELINE_FILE.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        _mode, scene_files, product_files, name = line.split("\t")
        baseline[name] = SceneDir(
            name=name,
            scene_files=int(scene_files),
            product=products.get(name.replace("-", "").replace("_", "")),
            product_files=int(product_files),
        )
    return baseline


def write_baseline(current: dict[str, SceneDir]) -> None:
    # Sorted by directory, not by the rendered line: a changed count then moves one
    # line in place instead of reordering the file.
    lines = [f"{d.mode}\t{d.scene_files}\t{d.product_files}\t{d.name}" for _, d in sorted(current.items())]
    body = "\n".join(lines) + ("\n" if lines else "")
    BASELINE_FILE.write_text(BASELINE_HEADER + body)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--regenerate-baseline",
        action="store_true",
        help="Rewrite the baseline from the current tree.",
    )
    args = parser.parse_args()

    current = scan_current()

    print("=" * 72)
    print("Scene/product split guard (merge-queue lane granularity)")
    print("=" * 72)

    if args.regenerate_baseline:
        write_baseline(current)
        enforced = sum(1 for d in current.values() if d.mode == "enforce")
        coupled = sum(d.scene_files for d in current.values() if d.product)
        print(f"\n  Regenerated {BASELINE_FILE.relative_to(REPO_ROOT)}")
        print(f"  {len(current)} scene dir(s); {enforced} enforced; {coupled} file(s) awaiting a move.")
        return 0

    baseline = read_baseline()

    # A new dir whose product already exists has one obvious home, so it fails. Not every
    # scene is a product though — onboarding, settings, billing and friends are app-level
    # and have nowhere to go, so an unowned new dir only warns.
    new_dirs = [d for name, d in sorted(current.items()) if name not in baseline and d.product]
    new_unowned = [d for name, d in sorted(current.items()) if name not in baseline and not d.product]
    grew_enforced: list[tuple[SceneDir, int]] = []
    grew_observed: list[tuple[SceneDir, int]] = []
    shrank: list[tuple[SceneDir, int]] = []

    for name, d in sorted(current.items()):
        if name not in baseline:
            continue
        was = baseline[name].scene_files
        if d.scene_files > was:
            (grew_enforced if baseline[name].mode == "enforce" else grew_observed).append((d, was))
        elif d.scene_files < was:
            shrank.append((d, was))

    # A fully emptied or deleted tree drops out of `current` entirely. That's the
    # largest possible win, so it has to surface as a shrink rather than silently
    # leaving a stale baseline entry behind.
    for name, was in sorted(baseline.items()):
        if name not in current:
            shrank.append(
                (
                    SceneDir(name=name, scene_files=0, product=was.product, product_files=was.product_files),
                    was.scene_files,
                )
            )

    coupled = sum(d.scene_files for d in current.values() if d.product)
    print(f"\n  Scene dirs: {len(current)}  ({sum(1 for d in current.values() if d.mode == 'enforce')} enforced)")
    print(f"  Files in a scene dir with a product counterpart: {coupled}")

    if new_dirs or grew_enforced:
        print()
        for d in new_dirs:
            print(
                f"::error file=frontend/src/scenes/{d.name}::"
                f"New scene directory '{d.name}' — products/{d.product}/ already exists, so this belongs in {d.destination}"
            )
        for d, was in grew_enforced:
            print(
                f"::error file=frontend/src/scenes/{d.name}::"
                f"'{d.name}' grew {was} -> {d.scene_files} files; {d.product_files} are already "
                f"in {d.destination} — put new files there"
            )

        if new_dirs:
            print(f"\n  ❌ {len(new_dirs)} new scene director(ies) for an existing product:")
            for d in new_dirs:
                print(f"     - {d.name}/  ({d.scene_files} files)  ->  {d.destination}")
        if grew_enforced:
            print(f"\n  ❌ {len(grew_enforced)} enforced tree(s) grew:")
            for d, was in grew_enforced:
                print(
                    f"     - {d.name}/  {was} -> {d.scene_files} files  ({d.product_files} already in {d.destination})"
                )

        print("\n  A change under frontend/ reports every merge-queue target and serializes")
        print("  against every other frontend PR. A change under products/<name>/frontend/")
        print("  reports one. See products/README.md for product frontend layout.")
        print("\n  If a file genuinely cannot move yet, say why in the PR and regenerate:")
        print("    python .github/scripts/check-scene-product-split.py --regenerate-baseline")
        return 1

    if new_unowned:
        print(f"\n  ⚠️  {len(new_unowned)} new scene director(ies) with no product counterpart:")
        for d in new_unowned:
            print(f"     - {d.name}/  ({d.scene_files} files)")
        print("\n  App-level scenes (settings, onboarding, billing) legitimately live here.")
        print("  Anything product-shaped should be a product instead — see products/README.md")
        print("  and `bin/hogli product:bootstrap <name>`. Regenerate to record it either way.")

    if grew_observed:
        print(f"\n  ⚠️  {len(grew_observed)} scene tree(s) grew (not failing):")
        for d, was in grew_observed:
            where = (
                f"destination {d.destination} has {d.product_files}, so the migration hasn't reached halfway"
                if d.product
                else "app-level scene, no product counterpart"
            )
            print(f"     - {d.name}/  {was} -> {d.scene_files} files  ({where})")
        print("\n  Regenerate to bank the new count, or move the files instead.")

    if shrank:
        print(f"\n  ✅ {len(shrank)} tree(s) shrank since baseline (regenerate to lock it in):")
        for d, was in sorted(shrank, key=lambda pair: pair[0].name):
            gone = " — fully migrated" if d.scene_files == 0 else ""
            print(f"     - {d.name}/  {was} -> {d.scene_files} files{gone}")
        print("\n  Run: python .github/scripts/check-scene-product-split.py --regenerate-baseline")

    if not grew_observed and not shrank and not new_unowned:
        print("\n✅ No new scene/product coupling. Baseline matches.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
